function getBorderForToken(backgroundDesignToken) {
  //If the background color isn't a data-vis design token, then we just say black.
  if (/\$color-data-vis/.test(backgroundDesignToken)) {
    var result = /(blue|purple|magenta|red|orange|yellow|green|teal|cyan|plum|pink)-([1-8]00)$/.exec(backgroundDesignToken);
    if (result != null && result.length >= 3) {
      var color = result[1];
      var level = Number(result[2]);
      if (level <= 700) {
        level += 200; //darken it.
      } else if (level <= 800) {
        level += 100; //darken as much as we can.
      }

      return "$color-data-vis-".concat(color, "-").concat(level);
    }
  }

  //If we can't find it, we will just return black.
  return (0, _getDesignTokens.getDesignTokenValue)('$color-black');
}

